   var closed=new NativeSourceHealingCast.Cast(null,null,null,Map.of());closed.close();c.nativeSourceHealingCast=closed;check(NativeSourceNoneTargetRequest.request(request,pc,76)==request,"closed prior cast does not fall through to fresh source metadata");c.nativeSourceHealingCast=null;var first=c.nativeSourceFirstPlayers;c.nativeSourceFirstPlayers=new NativeSourceFirstPlayers.Snapshot(Map.of());check(NativeSourceNoneTargetRequest.request(request,pc,76)==request,"missing published source proof does not capture a new role/life/pose");c.nativeSourceFirstPlayers=first;set(c,"phase","WORLD");check(NativeSourceNoneTargetRequest.request(request,pc,76)==request,"WORLD original packet target and coordinates retained");set(c,"phase","BATTLE");c.nativeSourceFirstPlayers=null;check(NativeSourceNoneTargetRequest.request(request,pc,76)==request,"unmarked Context remains original");c.nativeSourceFirstPlayers=first;rows.set(null,Map.of(29,attack));check(NativeSourceNoneTargetRequest.request(request,pc,76)==request,"missing metadata cannot create new Source remap authority");rows.set(null,Map.of());check(NativeSourceNoneTargetRequest.request(request,pc,76)==request,"unloaded metadata retains original request");check(NativeSourceNoneTargetRequest.class.getDeclaredFields().length==0,"field-free adapter retains no actor/row/Context/Frame/registry");
